mapper.select:

SELECT l.id, l.biz_date, l.create_time, l.change_type,
       CASE WHEN l.inv_doc_id IS NOT NULL THEN 'INV_DOC' ELSE 'INV_COUNT' END AS doc_type,
       d.kind AS doc_kind, COALESCE(l.inv_doc_id, l.count_id) AS doc_id, l.doc_no,
       l.warehouse_id, w.name AS warehouse_name, l.material_sku_id, l.change_qty, l.balance_qty, l.dye_lot, l.create_by,
       l.unit_price, l.amount, l.stock_unit, l.currency, l.valuation_status, l.reversal_of_log_id
FROM inv_stock_log l
JOIN bas_warehouse w ON w.id = l.warehouse_id
LEFT JOIN inv_doc d ON d.id = l.inv_doc_id
WHERE true
AND l.warehouse_id = #{q.warehouseId}
AND l.material_sku_id = #{q.materialSkuId}

    AND l.change_type IN #{t}

AND l.biz_date >= #{q.bizDateFrom}
AND l.biz_date <= #{q.bizDateTo}

    AND l.id IN #{id}




    AND l.id IN (
        SELECT l.id FROM inv_stock_log l WHERE true

        AND (upper(l.doc_no) LIKE #{keywordPrefix}
             OR upper(l.doc_no) IN #{code})
        UNION
        SELECT l.id FROM inv_stock_log l WHERE true

        AND l.dye_lot ILIKE #{keywordContains}
        UNION
        SELECT l.id FROM inv_stock_log l WHERE true

        AND l.material_sku_id IN (
            SELECT k.id FROM bas_material_sku k WHERE upper(k.code) LIKE #{keywordPrefix}
            OR upper(k.code) IN #{code}
            UNION
            SELECT k.id FROM bas_material m JOIN bas_material_sku k ON k.material_id = m.id
            WHERE m.name ILIKE #{keywordContains}
            OR upper(m.code) IN #{code}
        )
    )

ORDER BY l.id DESC


SELECT l.id, l.biz_date, l.create_time, l.change_type,
       CASE WHEN l.inv_doc_id IS NOT NULL THEN 'INV_DOC' ELSE 'INV_COUNT' END AS doc_type,
       d.kind AS doc_kind, COALESCE(l.inv_doc_id, l.count_id) AS doc_id, l.doc_no,
       l.warehouse_id, w.name AS warehouse_name, l.material_sku_id, l.change_qty, l.balance_qty, l.dye_lot, l.create_by,
       l.unit_price, l.amount, l.stock_unit, l.currency, l.valuation_status, l.reversal_of_log_id
FROM inv_stock_log l
JOIN bas_warehouse w ON w.id = l.warehouse_id
LEFT JOIN inv_doc d ON d.id = l.inv_doc_id
WHERE true
AND l.warehouse_id = #{q.warehouseId}
AND l.material_sku_id = #{q.materialSkuId}

    AND l.change_type IN #{t}

AND l.biz_date >= #{q.bizDateFrom}
AND l.biz_date <= #{q.bizDateTo}

    AND l.id IN #{id}




    AND l.id IN (
        SELECT l.id FROM inv_stock_log l WHERE true

        AND (upper(l.doc_no) LIKE #{keywordPrefix}
             OR upper(l.doc_no) IN #{code})
        UNION
        SELECT l.id FROM inv_stock_log l WHERE true

        AND l.dye_lot ILIKE #{keywordContains}
        UNION
        SELECT l.id FROM inv_stock_log l WHERE true

        AND l.material_sku_id IN (
            SELECT k.id FROM bas_material_sku k WHERE upper(k.code) LIKE #{keywordPrefix}
            OR upper(k.code) IN #{code}
            UNION
            SELECT k.id FROM bas_material m JOIN bas_material_sku k ON k.material_id = m.id
            WHERE m.name ILIKE #{keywordContains}
            OR upper(m.code) IN #{code}
        )
    )

AND l.create_time >= (CAST(#{q.createdDateFrom} AS date)::timestamp AT TIME ZONE 'Asia/Shanghai')
AND l.create_time < ((CAST(#{q.createdDateTo} AS date) + 1)::timestamp AT TIME ZONE 'Asia/Shanghai')
AND (l.create_time, l.id) < (#{afterTime}, #{afterId})
ORDER BY l.create_time DESC, l.id DESC
LIMIT #{limit}
